import{_ as r,a as s}from"./chunks/connection-success.DOvdEz_S.js";import{_ as l,B as p,o as u,c as d,ax as a,j as t,a as o,E as n}from"./chunks/framework.Bnt0oLax.js";const h="/docs/assets/github-install-authorize-request.BVoeXi2r.png",g="/docs/assets/installation-request-submitted.DDwZXmG2.png",m="/docs/assets/select-github-installation.BZm1W2fr.png",T=JSON.parse('{"title":"Admin Approval","description":"Request and complete GitHub connection when your organization requires administrator approval before installing external apps","frontmatter":{"description":"Request and complete GitHub connection when your organization requires administrator approval before installing external apps"},"headers":[],"relativePath":"custom-widgets/v2/admin-approval.md","filePath":"custom-widgets/v2/admin-approval.md"}'),c={name:"custom-widgets/v2/admin-approval.md"};function q(b,e,y,f,v,w){const i=p("GitHubButton");return u(),d("div",null,[e[23]||(e[23]=a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/admin-approval.md for this page in Markdown format</div><h1 id="admin-approval" tabindex="-1">Admin Approval <a class="header-anchor" href="#admin-approval" aria-label="Permalink to &quot;Admin Approval&quot;">​</a></h1><p>When connecting your GitHub repositories to the platform, some GitHub Enterprise organizations enforce security policies that require administrator approval before external applications can be installed. This guide explains what happens when admin approval is required and how to complete the setup once approved.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A GitHub account with access to your organization</li><li>Knowledge that your organization uses GitHub Enterprise with approval policies</li><li>(Optional) Contact information for your GitHub organization admin</li></ul><p><strong>This guide is for you if:</strong></p><ul><li>Your organization uses GitHub Enterprise with strict security policies</li><li>You see a &quot;pending approval&quot; message after attempting to connect GitHub</li><li>Your GitHub organization admin needs to approve external app installations</li></ul><h2 id="which-flow-will-you-see" tabindex="-1">Which Flow Will You See <a class="header-anchor" href="#which-flow-will-you-see" aria-label="Permalink to &quot;Which Flow Will You See&quot;">​</a></h2>',8)),t("p",null,[e[0]||(e[0]=o("When you click ",-1)),n(i),e[1]||(e[1]=o(", you'll experience one of two flows depending on whether the app is already installed on your organization:",-1))]),e[24]||(e[24]=a('<table tabindex="0"><thead><tr><th>Scenario</th><th>What You&#39;ll See</th><th>This Guide?</th></tr></thead><tbody><tr><td><strong>App not installed on your org</strong></td><td>GitHub&#39;s installation wizard with &quot;Install&quot; or &quot;Request&quot; button</td><td>Yes</td></tr><tr><td><strong>App already installed</strong> (by you or another community member)</td><td>Picker showing existing installations to connect</td><td>No approval needed</td></tr></tbody></table><p><strong>How to tell which scenario you&#39;re in:</strong></p><ul><li>If you see a list of organizations with &quot;Install&quot; or &quot;Request&quot; buttons → <strong>New installation flow</strong> (this guide)</li><li>If you see a picker listing existing installations to select → <strong>Already installed</strong> (just pick and connect)</li></ul><h2 id="new-installation-flow-admin-approval-required" tabindex="-1">New Installation Flow (Admin Approval Required) <a class="header-anchor" href="#new-installation-flow-admin-approval-required" aria-label="Permalink to &quot;New Installation Flow (Admin Approval Required)&quot;">​</a></h2><p>This section covers what happens when you&#39;re installing the app on an organization for the first time and that organization requires admin approval.</p><h3 id="step-1-initiate-github-connection" tabindex="-1">Step 1: Initiate GitHub Connection <a class="header-anchor" href="#step-1-initiate-github-connection" aria-label="Permalink to &quot;Step 1: Initiate GitHub Connection&quot;">​</a></h3>',6)),t("p",null,[e[2]||(e[2]=o("Go to ",-1)),e[3]||(e[3]=t("strong",null,"Integrations",-1)),e[4]||(e[4]=o(" → ",-1)),e[5]||(e[5]=t("strong",null,"Developer Studio",-1)),e[6]||(e[6]=o(" → ",-1)),e[7]||(e[7]=t("strong",null,"Sources",-1)),e[8]||(e[8]=o(" and click ",-1)),n(i),e[9]||(e[9]=o(":",-1))]),e[25]||(e[25]=a('<p><img src="'+r+'" alt="Screenshot placeholder: Sources page" data-zoomable="true"></p><p>You&#39;ll be redirected to GitHub to authorize the application.</p><h3 id="step-2-request-installation" tabindex="-1">Step 2: Request Installation <a class="header-anchor" href="#step-2-request-installation" aria-label="Permalink to &quot;Step 2: Request Installation&quot;">​</a></h3><p>On GitHub, you&#39;ll see the installation page where you select your organization and repositories:</p><p><img src="'+h+'" alt="Screenshot placeholder: GitHub installation request" data-zoomable="true"></p><p><strong>What you&#39;ll see on this page:</strong></p><ul><li><strong>Organization selector</strong>: Choose which organization to install on</li><li><strong>Repository access</strong>: Select &quot;All repositories&quot; or &quot;Only select repositories&quot;</li><li><strong>Request tag</strong>: Repositories requiring admin approval show a <code>request</code> tag</li><li><strong>Permissions</strong>: The app requests &quot;Read access to code and metadata&quot;</li></ul><p><strong>To request installation:</strong></p><ol><li>Select your organization from the dropdown</li><li>Choose which repositories to grant access to</li><li>Notice the <code>request</code> tag next to repositories requiring approval</li><li>Click <strong>Install, Authorize, &amp; Request</strong> to submit your request</li></ol><h3 id="step-3-approval-pending-page" tabindex="-1">Step 3: Approval Pending Page <a class="header-anchor" href="#step-3-approval-pending-page" aria-label="Permalink to &quot;Step 3: Approval Pending Page&quot;">​</a></h3><p>After submitting your request, GitHub redirects you back to a confirmation page in the platform:</p><p><img src="'+g+'" alt="Screenshot placeholder: Approval pending" data-zoomable="true"></p><p><strong>This page shows:</strong></p><ul><li><strong>&quot;Installation Request Submitted&quot;</strong> — confirming your request reached your organization admin</li><li><strong>What happens next</strong> — three numbered steps explaining the approval and reconnection process</li><li><strong>&quot;Return to Sources&quot;</strong> link — takes you back to your Sources settings page</li></ul><p><strong>While waiting for approval:</strong></p>',15)),t("ul",null,[e[12]||(e[12]=t("li",null,"You can close the browser window — no action is needed until approval",-1)),e[13]||(e[13]=t("li",null,[o("If you have the Sources page open in another tab, it will "),t("strong",null,"automatically detect"),o(" when approval is granted")],-1)),t("li",null,[e[10]||(e[10]=o("The approval request does not expire, but your browser session may — you'll need to click ",-1)),n(i),e[11]||(e[11]=o(" again after approval",-1))])]),e[26]||(e[26]=a('<blockquote><p><strong>Note</strong>: If you&#39;ve been waiting for more than a few days, follow up with your organization admin to check the status of your request.</p></blockquote><h3 id="step-4-admin-approves-the-request" tabindex="-1">Step 4: Admin Approves the Request <a class="header-anchor" href="#step-4-admin-approves-the-request" aria-label="Permalink to &quot;Step 4: Admin Approves the Request&quot;">​</a></h3><p>Your GitHub organization admin will:</p><ol><li>Receive a notification about the pending installation request</li><li>Review the app&#39;s requested permissions</li><li>Approve or deny the installation</li></ol><blockquote><p><strong>Note</strong>: This process may take hours or days depending on your organization&#39;s approval workflow.</p></blockquote><h3 id="step-5-complete-the-connection" tabindex="-1">Step 5: Complete the Connection <a class="header-anchor" href="#step-5-complete-the-connection" aria-label="Permalink to &quot;Step 5: Complete the Connection&quot;">​</a></h3><p>Once your admin approves the installation:</p>',7)),t("ol",null,[e[16]||(e[16]=t("li",null,"Return to your Sources settings page",-1)),t("li",null,[e[14]||(e[14]=o("Click ",-1)),n(i),e[15]||(e[15]=o(" again",-1))]),e[17]||(e[17]=t("li",null,"Complete the standard OAuth flow",-1)),e[18]||(e[18]=t("li",null,"Select your installation from the picker",-1))]),e[27]||(e[27]=a('<p><img src="'+m+'" alt="Screenshot placeholder: Select installation" data-zoomable="true"></p><ol start="5"><li>You&#39;ll see the success confirmation screen</li></ol><p><img src="'+s+'" alt="Screenshot placeholder: Connection successful" data-zoomable="true"></p><p>Your GitHub repositories are now connected and ready to use.</p><h2 id="what-if-approval-is-denied" tabindex="-1">What If Approval Is Denied <a class="header-anchor" href="#what-if-approval-is-denied" aria-label="Permalink to &quot;What If Approval Is Denied&quot;">​</a></h2><p>If your organization admin denies the installation request:</p><ol><li><strong>You won&#39;t receive a notification</strong> — the request won&#39;t be approved</li><li><strong>Contact your admin</strong> to understand why it was denied</li><li><strong>Address any concerns</strong> they may have about the application</li><li><strong>Submit a new request</strong> once issues are resolved</li></ol><p>Common reasons for denial:</p><ul><li>Security policy restrictions on third-party apps</li><li>Need for additional review or documentation</li><li>Temporary freeze on new app installations</li></ul><h2 id="what-happens-behind-the-scenes" tabindex="-1">What Happens Behind the Scenes <a class="header-anchor" href="#what-happens-behind-the-scenes" aria-label="Permalink to &quot;What Happens Behind the Scenes&quot;">​</a></h2><p>For a new installation, your request waits with GitHub until your organization admin approves it — then you return and reconnect. If the app is already installed on your organization, you skip the wait entirely and connect through the picker. If you&#39;re the GitHub organization administrator approving these requests, see <a href="./approve-github-access.html">Approve GitHub Access</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="i-don-t-see-my-organization-in-the-list" tabindex="-1">&quot;I don&#39;t see my organization in the list&quot; <a class="header-anchor" href="#i-don-t-see-my-organization-in-the-list" aria-label="Permalink to &quot;&quot;I don&#39;t see my organization in the list&quot;&quot;">​</a></h3><p><strong>Possible causes:</strong></p><ul><li>You&#39;re not a member of that GitHub organization</li><li>The organization has restricted app installations to admins only</li><li>You need to re-authenticate with GitHub</li></ul><p><strong>Solution:</strong></p><ol><li>Verify your GitHub organization membership</li><li>Contact your GitHub admin to check organization settings</li><li>Try signing out and back into GitHub</li></ol><h3 id="my-admin-approved-but-i-still-can-t-connect" tabindex="-1">&quot;My admin approved but I still can&#39;t connect&quot; <a class="header-anchor" href="#my-admin-approved-but-i-still-can-t-connect" aria-label="Permalink to &quot;&quot;My admin approved but I still can&#39;t connect&quot;&quot;">​</a></h3><p><strong>Solution:</strong></p>',19)),t("ol",null,[t("li",null,[e[19]||(e[19]=o("Make sure you're clicking ",-1)),n(i),e[20]||(e[20]=o(" again after approval",-1))]),e[21]||(e[21]=t("li",null,"You must complete the OAuth flow again — approval alone doesn't connect you",-1)),e[22]||(e[22]=t("li",null,"Select your organization's installation from the picker",-1))]),e[28]||(e[28]=a('<h3 id="the-approval-is-taking-too-long" tabindex="-1">&quot;The approval is taking too long&quot; <a class="header-anchor" href="#the-approval-is-taking-too-long" aria-label="Permalink to &quot;&quot;The approval is taking too long&quot;&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Check with your GitHub organization admin</li><li>Ask them to check <strong>Settings</strong> → <strong>Third-party access</strong> → <strong>Pending requests</strong></li><li>The request may be in a queue or require additional review</li></ol><h3 id="i-see-request-instead-of-install-for-my-organization" tabindex="-1">&quot;I see &#39;Request&#39; instead of &#39;Install&#39; for my organization&quot; <a class="header-anchor" href="#i-see-request-instead-of-install-for-my-organization" aria-label="Permalink to &quot;&quot;I see &#39;Request&#39; instead of &#39;Install&#39; for my organization&quot;&quot;">​</a></h3><p><strong>This is expected.</strong> It means your organization requires admin approval. Follow the steps in this guide to request and complete the installation.</p><p>For more troubleshooting help, see <a href="./common-issues.html">Common Issues</a>.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="how-long-does-approval-take" tabindex="-1">How long does approval take? <a class="header-anchor" href="#how-long-does-approval-take" aria-label="Permalink to &quot;How long does approval take?&quot;">​</a></h3><p>Approval time depends on your organization&#39;s policies. It can range from minutes to several days. Contact your GitHub admin for your organization&#39;s typical approval timeline.</p><h3 id="do-i-need-to-request-approval-every-time" tabindex="-1">Do I need to request approval every time? <a class="header-anchor" href="#do-i-need-to-request-approval-every-time" aria-label="Permalink to &quot;Do I need to request approval every time?&quot;">​</a></h3><p>No. Once the app is approved and installed, you won&#39;t need approval again unless:</p><ul><li>The app is uninstalled and needs to be reinstalled</li><li>The app requests additional permissions</li></ul><h3 id="can-i-use-a-different-organization-while-waiting" tabindex="-1">Can I use a different organization while waiting? <a class="header-anchor" href="#can-i-use-a-different-organization-while-waiting" aria-label="Permalink to &quot;Can I use a different organization while waiting?&quot;">​</a></h3><p>Yes. If you have access to other GitHub organizations that don&#39;t require approval (or are already approved), you can connect those while waiting.</p><h3 id="someone-else-in-my-org-already-installed-the-app-do-i-need-approval" tabindex="-1">Someone else in my org already installed the app. Do I need approval? <a class="header-anchor" href="#someone-else-in-my-org-already-installed-the-app-do-i-need-approval" aria-label="Permalink to &quot;Someone else in my org already installed the app. Do I need approval?&quot;">​</a></h3><p>No. If the app is already installed on your organization (by another community member or team member), you won&#39;t see the &quot;Request&quot; button. Instead, you&#39;ll go through the simple OAuth flow and see a picker to select the existing installation. No admin approval is needed in this case.</p><h3 id="what-permissions-does-the-app-request" tabindex="-1">What permissions does the app request? <a class="header-anchor" href="#what-permissions-does-the-app-request" aria-label="Permalink to &quot;What permissions does the app request?&quot;">​</a></h3><p>The application requests:</p><ul><li><strong>Repository access</strong>: To read widget, script, and stylesheet files from your repositories</li><li><strong>Webhooks</strong>: To receive notifications when you push changes</li><li><strong>Metadata</strong>: To list available repositories</li></ul><h3 id="is-my-code-safe" tabindex="-1">Is my code safe? <a class="header-anchor" href="#is-my-code-safe" aria-label="Permalink to &quot;Is my code safe?&quot;">​</a></h3><p>See <a href="./content-security.html">Content Security</a> for how the platform handles your repository content.</p><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><p>If you continue to experience issues:</p><ol><li><strong>Check this guide</strong> for troubleshooting steps</li><li><strong>Contact your GitHub admin</strong> for approval-related issues</li><li><strong>Talk to your Gainsight team</strong> if the issue persists after admin approval</li></ol><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./connect-github.html">Connect Your GitHub Account</a> — Standard connection flow</li><li><a href="./repository-settings.html">Repository &amp; Branch Settings</a> — Configure repositories after connection</li><li><a href="./common-issues.html">Common Issues</a> — More troubleshooting help</li></ul>',26))])}const z=l(c,[["render",q]]);export{T as __pageData,z as default};
